select drex.decide(JSON_OBJECT('subject', subject, 'body', body), JSON '{"refund": {"type": "noul", "instructions": "Is a refund needed?"}, "outage": {"type": "noul", "criteria": {"true": "Many users can\'t work", "false": null}}, "team": {"type": "choice", "instructions": "Which team?", "criteria": [{"label": "billing", "description": "Payments"}, {"label": "technical", "description": null}]}, "urgency": {"type": "score", "instructions": "How urgent?", "criteria": ["low", "high"]}}', NULL) as answer from tickets
